mapper.select:
    SELECT DISTINCT u.user_id uid FROM (
  SELECT f.focus_user_id uid FROM user_focus f JOIN user_focus back ON back.user_id=f.focus_user_id AND back.focus_user_id=f.user_id WHERE f.user_id=#{me}
  UNION SELECT IF(d.user_low_id=#{me},d.user_high_id,d.user_low_id) uid FROM direct_chat_state d WHERE (d.user_low_id=#{me} OR d.user_high_id=#{me}) AND d.state='ACCEPTED'
) candidates JOIN user_info u ON u.user_id=candidates.uid WHERE u.status=1
AND NOT EXISTS(SELECT 1 FROM user_block b WHERE (b.user_id=#{me} AND b.blocked_user_id=u.user_id) OR (b.user_id=u.user_id AND b.blocked_user_id=#{me}))
